import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.VoxelShapes{Shapes: []protocol.VoxelShape{{Cells: protocol.VoxelCells{XSize: 2, YSize: 1, ZSize: 3,
# Storage: []uint8{0x00, 0x01, 0x80, 0xff}}, XCoordinates: []float32{0, 0.5, 1}, YCoordinates: []float32{0, 1},
# ZCoordinates: []float32{0, 0.25, 0.75, 1}}},
# NameMap: []protocol.VoxelShapeNameEntry{{Name: "minecraft:slab", ID: 258}}, CustomShapeCount: 300}
SLAB = bytes.fromhex(
    "0102010304000180ff03000000000000003f0000803f02000000000000803f04000000000000803e0000403f0000803f"
    "010e6d696e6563726166743a736c616202012c01"
)

# generated by gophertunnel b8bd735:
# packet.VoxelShapes{CustomShapeCount: 258}
EMPTY = bytes.fromhex("00000201")

# generated by gophertunnel b8bd735:
# packet.VoxelShapes{Shapes: []protocol.VoxelShape{{Cells: protocol.VoxelCells{XSize: 1, YSize: 1, ZSize: 1,
# Storage: make([]uint8, 200)}, XCoordinates: []float32{0}, YCoordinates: []float32{0}, ZCoordinates: []float32{0}}}}
LONG_STORAGE = bytes.fromhex(
    ""
)

GOLDENS = [
    pytest.param(
        v2225.VoxelShapesPacket(
            shapes=[
                v2225.SerializableVoxelShape(
                    cells=v2225.SerializableCells(x_size=2, y_size=1, z_size=3, storage=[0x00, 0x01, 0x80, 0xFF]),
                    x_coords=[0.0, 0.5, 1.0],
                    y_coords=[0.0, 1.0],
                    z_coords=[0.0, 0.25, 0.75, 1.0],
                )
            ],
            name_map={"minecraft:slab": v2225.RegistryHandle(value=258)},
            custom_shape_count=300,
        ),
        SLAB,
        id="slab",
    ),
    pytest.param(v2225.VoxelShapesPacket(custom_shape_count=258), EMPTY, id="empty"),
    pytest.param(
        v2225.VoxelShapesPacket(
            shapes=[
                v2225.SerializableVoxelShape(
                    cells=v2225.SerializableCells(x_size=1, y_size=1, z_size=1, storage=[0] * 200),
                    x_coords=[0.0],
                    y_coords=[0.0],
                    z_coords=[0.0],
                )
            ]
        ),
        LONG_STORAGE,
        id="long-storage",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_voxel_shapes_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_voxel_shapes_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
